        CH("When is the i- form used?", ["When an active -um- or mag- verb has a direct object", "Only with names of people", "Only in the past tense"], "When an active -um- or mag- verb has a direct object", "Ask 'Bumilí what?' to find the direct object."),
        CH("\"Bumilí ng isdâ ang babáe para sa kanyáng iná.\" What is the direct object?", ["isdâ", "ang babáe", "para sa kanyáng iná"], "isdâ", "Ang babáe is the subject; para sa kanyáng iná is the indirect object."),
        CH("An i- verb is usually the passive form of which kind of verb?", ["mag-", "-um-", "ma-"], "mag-", "Seldom of an -um- verb."),
        CH("What is the PAST of isulat?", ["isinúlat", "isusúlat", "isinusúlat"], "isinúlat", "i- + -in- after the first letter of the root."),
        CH("What is the FUTURE of isáma?", ["isasáma", "isináma", "isinasáma"], "isasáma", "i- + first syllable repeated + root."),
        CH("What is the PRESENT of ihánap?", ["inihahánap", "inihánap", "ihahánap"], "inihahánap", "Roots starting with h take -ni-."),
        CH("Roots beginning with a vowel or h, l, y, w use which infix in the past and present?", ["-ni-", "-in-", "-um-"], "-ni-", "inihánap, inilutò."),
        CH("What is the past of ipagsulát?", ["ipinagsulát", "ipagsusulát", "isinúlat"], "ipinagsulát", "-in- goes after the first two letters of ipag-."),
        CH("Pattern 1 (-um- verb): what becomes the subject of the i- sentence?", ["the indirect object", "the direct object", "the doer"], "the indirect object", "Ibinilí ng babáe ng isdâ ang kanyáng iná."),
        CH("Pattern 2 (mag- verb): what becomes the subject of the i- sentence?", ["the direct object", "the indirect object", "the doer"], "the direct object", "Inilutò niyá ang pagkain para sa anák."),
